import{_ as r,o,c as d,a2 as s}from"./chunks/framework.BXyf8PVu.js";const p=JSON.parse('{"title":"ESG","description":"","frontmatter":{"title":"ESG"},"headers":[],"relativePath":"jp/blogs/CFA/C4 Corporate Finance/M2 ESG.md","filePath":"jp/blogs/CFA/C4 Corporate Finance/M2 ESG.md"}'),n={name:"jp/blogs/CFA/C4 Corporate Finance/M2 ESG.md"};function g(a,t,l,e,i,h){return o(),d("div",null,[...t[0]||(t[0]=[s('<h1 id="投資分析における環境・社会・ガバナンス-esg-の考慮" tabindex="-1">投資分析における環境・社会・ガバナンス（ESG）の考慮 <a class="header-anchor" href="#投資分析における環境・社会・ガバナンス-esg-の考慮" aria-label="Permalink to &quot;投資分析における環境・社会・ガバナンス（ESG）の考慮&quot;">​</a></h1><p>所有構造がコーポレート・ガバナンスをどう形づくるか、会社のガバナンスをどう評価するか、そして ESG のリスクと機会をどう特定し、株式と信用の分析に組み込むかを扱う。概念中心の単元で、覚えるべき式はない。</p><table tabindex="0"><thead><tr><th>用語</th><th>意味</th></tr></thead><tbody><tr><td><strong>支配株主</strong></td><td>支配権を行使できる個人または集団（一族、他の会社、国家）。株式の<strong>過半数</strong>（&gt; 50%）を持つ場合<strong>も少数</strong>（&lt; 50%）の場合もある</td></tr><tr><td><strong>プリンシパル・エージェント問題</strong></td><td>経営者が会社の資源を株主のためではなく自分の利益のために使う</td></tr><tr><td><strong>プリンシパル・プリンシパル問題</strong></td><td>支配株主が少数株主を犠牲にして資源を得る</td></tr><tr><td><strong>議決権の上限</strong></td><td>大口保有の議決権に対する法的な制限（戦略的企業の外国支配を防ぐために政府がよく使う）</td></tr><tr><td><strong>役員の兼任（インターロッキング）</strong></td><td>同じ人々が複数の会社の取締役会に就いている（ラテンアメリカで一般的）</td></tr><tr><td><strong>内部者</strong></td><td>株主でもある経営者や取締役</td></tr><tr><td><strong>株主アクティビズム</strong></td><td>株主が会社に特定の行動をとらせるために使う戦略</td></tr><tr><td><strong>ESG インテグレーション</strong></td><td>証券・業界の分析<strong>とポートフォリオ構築</strong>において、定性的・定量的な ESG 要因を使うこと</td></tr><tr><td><strong>座礁資産</strong></td><td>規制や需要の変化などで陳腐化したり採算がとれなくなったりした資産</td></tr><tr><td><strong>グリーンウォッシング</strong></td><td>グリーンボンドの調達資金が実際には環境に有益なプロジェクトに使われないリスク</td></tr></tbody></table><h2 id="所有構造" tabindex="-1">所有構造 <a class="header-anchor" href="#所有構造" aria-label="Permalink to &quot;所有構造&quot;">​</a></h2><ul><li><strong>分散所有</strong>：株主が多く、単独で支配できる者はいない。</li><li><strong>集中所有</strong>：1 人の株主または集団（支配株主）が支配権を行使できる。</li><li><strong>ハイブリッド</strong>：その中間。</li></ul><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>決まった割合の線引きはない。所有だけでは誰が会社を支配しているかわからないことがある。支配株主は、以下の仕組みを通じて株式の<strong>過半数でも少数でも</strong>持ちうる。（テキストで唯一出てくる「25%」は英国の説明で、英国では 25% 以上を持つ株主がいる会社は少ない。）</p></div><p>集中所有の方がはるかに一般的で、OECD（2017）が調査した 47 の法域のうち <strong>38</strong> がそうである。</p><table tabindex="0"><thead><tr><th>分類</th><th>法域</th><th>備考</th></tr></thead><tbody><tr><td><strong>分散</strong></td><td>オーストラリア、アイルランド、英国、米国</td><td>オーストラリア：株式の多くは金融機関が保有。米国の上場企業に支配株主がいることはまれ</td></tr><tr><td><strong>ハイブリッド</strong></td><td>カナダ、ドイツ、日本、オランダ、スイス</td><td>例：ドイツでは多くの会社が強く支配されているが、上場株式は広く保有されている</td></tr><tr><td><strong>集中</strong></td><td>残りの 38（例：中国、フランス、インド、ブラジル、韓国）</td><td>国家：中国、ノルウェー、スウェーデン。一族：ブラジル、メキシコ、ポルトガル、韓国。企業グループ：インド、ロシア</td></tr></tbody></table><p><strong>支配が所有を上回る仕組み：</strong></p><ul><li><strong>水平的所有</strong>：事業上の利害を共有する会社（主要な顧客や仕入先）が互いに株式を持ち合う。戦略的提携や長期的な関係を支える。</li><li><strong>垂直的（ピラミッド型）所有</strong>：ある会社やグループが 2 つ以上の持株会社を支配し、その持株会社が事業会社を支配する。</li><li><strong>種類株式（デュアル・クラス）</strong>：ある種類の株式は優越的な（または唯一の）議決権を持ち、他の種類は議決権が劣るかない。ピラミッドと組み合わせると、頂点のグループは自らに優越的議決権株式を与え、比較的少ない持株で事業会社を支配できる。</li></ul><h3 id="所有構造ごとの対立" tabindex="-1">所有構造ごとの対立 <a class="header-anchor" href="#所有構造ごとの対立" aria-label="Permalink to &quot;所有構造ごとの対立&quot;">​</a></h3><table tabindex="0"><thead><tr><th>所有</th><th>議決権</th><th>力関係</th><th>主な対立</th></tr></thead><tbody><tr><td>分散</td><td>分散</td><td>株主が弱く、<strong>経営者が強い</strong></td><td><strong>プリンシパル・エージェント</strong></td></tr><tr><td>集中</td><td>集中</td><td><strong>株主が強く</strong>、経営者が弱い</td><td><strong>プリンシパル・プリンシパル</strong></td></tr><tr><td>分散</td><td>集中</td><td>支配株主が<strong>過半数を持たない</strong>（種類株式、ピラミッドによる）</td><td><strong>プリンシパル・プリンシパル</strong></td></tr><tr><td>集中</td><td>分散</td><td><strong>議決権の上限</strong>から生じる</td><td>（テキストでは命名されていない）</td></tr></tbody></table><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>支配株主はプリンシパル・エージェント問題を<strong>減らす</strong>（取締役会を支配し、経営者を任命し、監視する動機を持つ）が、プリンシパル・プリンシパル問題を<strong>生み出す</strong>。</p></div><h3 id="影響力のある株主" tabindex="-1">影響力のある株主 <a class="header-anchor" href="#影響力のある株主" aria-label="Permalink to &quot;影響力のある株主&quot;">​</a></h3><table tabindex="0"><thead><tr><th>株主</th><th>役割と懸念</th></tr></thead><tbody><tr><td><strong>銀行</strong></td><td>欧州とアジアで一般的。貸し手<strong>であり</strong>株主でもある。不利な条件での多額の借入を会社に促し、他の株主を犠牲にすることがある</td></tr><tr><td><strong>一族</strong></td><td>ラテンアメリカで支配的で、アジアと欧州ではそれほどでもない。役員の兼任を伴うことが多い。<strong>+</strong> プリンシパル・エージェント問題が少ない。<strong>−</strong> 透明性が低い、経営者の説明責任が弱い、少数株主の権利を軽視する、優秀な経営者を集めにくい</td></tr><tr><td><strong>国有企業</strong></td><td>戦略的な部門、必要資本が民間の能力を超える場合、国家が一定の価格や基準で製品を提供したい場合（電力、医療）。上場した国有企業（<strong>混合所有</strong>）は市場の監視を受けにくく（暗黙の国家による倒産保証）、株主を犠牲にして公共政策を追求することがある</td></tr><tr><td><strong>機関投資家</strong></td><td>投資信託、年金基金、保険会社、ヘッジファンド。判断する資源と専門性がある。分散市場では支配できるほど大きいことはまれだが、取締役会と経営者に説明責任を果たさせることでよいガバナンスを促す</td></tr><tr><td><strong>企業グループ</strong></td><td>水平・垂直の構造で所有に見合わない支配を得る。株式の持ち合いは株式の譲渡を制限し、外部者を締め出す。少数株主に不利な<strong>関連当事者取引</strong>のリスクが高い（例：Samsung、三和、Grupo Carso）</td></tr><tr><td><strong>プライベート・エクイティ</strong></td><td>ベンチャー・キャピタル（初期段階、監督）と LBO ファンド（成熟企業の過半数支配）。企業行動規範や業績連動報酬をもたらすことがある</td></tr><tr><td><strong>外国人投資家</strong></td><td>新興市場で国内投資家より多く保有すると影響力を持つ。規制の厳しい法域の投資家は透明性の向上を求めることがある。より厳しい市場への重複上場は、現地の少数株主の利益になりうる</td></tr><tr><td><strong>内部者</strong></td><td>持株が大きい → 株主との利害の一致と長期志向。ただし大きな持株は自分たちの利益を守る力も与えうる</td></tr></tbody></table><h3 id="ガバナンスへの影響" tabindex="-1">ガバナンスへの影響 <a class="header-anchor" href="#ガバナンスへの影響" aria-label="Permalink to &quot;ガバナンスへの影響&quot;">​</a></h3><ul><li><strong>独立取締役</strong>：会社と重要な関係（雇用、所有、報酬）を持たない取締役。分散所有の法域で経営者の監視を強めるために生まれ、エンロンなどの不祥事の後にその割合が高まった。米国は、監査、指名、報酬の各委員会をすべて独立取締役で構成することを求めている。集中所有の法域の多くでは指名・報酬委員会は義務ではなく、独立取締役の役割は狭い。OECD 諸国は、最低人数（通常 1–3 人）か最低比率（通常 20% から 50% 超）を求めるか推奨している。</li><li><strong>取締役会の構造</strong>： <ul><li><strong>一層制</strong>：業務執行取締役と非業務執行取締役からなる単一の取締役会。最も一般的な構造。</li><li><strong>二層制</strong>：監査役会が執行役会を監督する。アルゼンチン、ドイツ、ロシアなどでは義務、ブラジルやフランスでは任意。監査役会は帳簿を調べ、年次報告書を審査し、監査人を監督し、経営陣の報酬を決めるか影響を与える。ドイツではステークホルダーの代表（銀行、労働者）が含まれる。</li></ul></li><li><strong>特別な議決の仕組み</strong>：少数株主が取締役の指名・選任に参加するのを助ける（例：ブラジル、インド、ポルトガル、トルコ、イタリア、イスラエル、英国）。英国では、支配株主のいるプレミアム上場企業は、独立取締役の選任について全株主<strong>と</strong>非支配株主の<strong>両方</strong>の承認を得なければならない。</li><li><strong>ガバナンス・コード、法律、上場規則</strong>：各国のコードは<strong>コンプライ・オア・エクスプレイン</strong>で運用される。日本はさらに進んでおり、社外取締役のいない会社は、選任が適切でない理由を説明しなければならない。国のコードがない場合は、会社法（例：チリ）や取引所の上場規則（例：インド）が適用される。</li><li><strong>スチュワードシップ・コード</strong>：投資家に権利の行使とエンゲージメントを促す、主に任意のコード。英国のスチュワードシップ・コードの下では、機関投資家は投資先企業を監視しなければならず、英国の資産運用会社はコンプライ・オア・エクスプレインの声明を公表しなければならない。</li></ul><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>集中所有の下ではプリンシパル・エージェント問題は一般に<strong>小さい</strong>。そのため、そこでは独立取締役の役割が狭い。</p></div><h2 id="コーポレート・ガバナンスの評価" tabindex="-1">コーポレート・ガバナンスの評価 <a class="header-anchor" href="#コーポレート・ガバナンスの評価" aria-label="Permalink to &quot;コーポレート・ガバナンスの評価&quot;">​</a></h2><p>有効なガバナンスは、高い収益性と ROE の成長、信用へのアクセスの改善、高く持続可能な配当、長期的によい株価パフォーマンス、そして<strong>低い資本コスト</strong>をもたらしうる。有効でないガバナンスは、評判の毀損、競争力の低下、弱い、あるいは不安定な株価、低い収益性、<strong>高い資本コスト</strong>をもたらす。</p><p>ガバナンスは数値化しにくい。まず開示された方針（企業倫理、贈収賄と汚職、内部通報者の保護、関連当事者取引を含む）から始め、次に経営陣と対話し、必要ならアクティビズムを使う。実務では、アナリストは<strong>リスク・プレミアム（資本コスト）や信用スプレッド</strong>を調整してガバナンスを反映する。</p><h3 id="取締役会の方針と慣行" tabindex="-1">取締役会の方針と慣行 <a class="header-anchor" href="#取締役会の方針と慣行" aria-label="Permalink to &quot;取締役会の方針と慣行&quot;">​</a></h3><table tabindex="0"><thead><tr><th>分野</th><th>見るべき点</th></tr></thead><tbody><tr><td><strong>CEO の兼任</strong></td><td>CEO が取締役会議長を兼ねる → 取締役会の監督が損なわれうる。議長が独立していなければ、<strong>筆頭独立取締役</strong>を置くことがある</td></tr><tr><td><strong>取締役会の独立性</strong></td><td>独立取締役がいない、あるいは少数にとどまるのは<strong>マイナス</strong>：経営陣が自己の利益のために行動しうる → 認識されるリスクが高まる</td></tr><tr><td><strong>委員会</strong></td><td>監査、ガバナンス、報酬、指名、リスク、コンプライアンス。主要な委員会が独立しているか確認する。独立していない、あるいは業務執行のメンバーは、報酬（報酬委員会）、経営者の選任（指名委員会）、報告の誠実性（監査委員会）で利益相反を生む</td></tr><tr><td><strong>スキルと経験</strong></td><td>スキルが偏りすぎていても、多様でも中核事業と無関係でも、どちらも不十分でありうる。資源やESG リスクの高い業種では、取締役会に環境、気候、社会の専門家が含まれるのが普通</td></tr><tr><td><strong>在任期間</strong></td><td><strong>10 年</strong>を超えると長い。<strong>+</strong> 事業と経営陣の実績を深く知っている。<strong>−</strong> 独立性を弱めうる（経営陣に近すぎる）し、変化に抵抗しうる</td></tr><tr><td><strong>構成</strong></td><td>取締役の人数と多様性（職業、文化・地理的背景、性別、年齢、在任期間）。人数が多すぎる、あるいは多様性が乏しすぎると統治の効果が下がりうる</td></tr><tr><td><strong>取締役会の評価</strong></td><td>自己評価または外部評価。職務、リーダーシップ、構造（委員会を含む）、取締役会と経営陣の関係を対象とする。株主、規制当局、その他のステークホルダー向けのことがある</td></tr></tbody></table><p><strong>役員報酬。</strong> 透明性、短期・長期のインセンティブの基準、会社の戦略との結びつき、CEO と平均的な従業員の報酬格差を見る。過大な報酬（しばしば CEO 報酬 ÷ 平均的な従業員の報酬）は KPI と照らして判断する。インセンティブは企業価値を高めているか。</p><ul><li><strong>セイ・オン・ペイ</strong>：<strong>株主</strong>が報酬について投票したり意見を述べたりできる。</li><li><strong>クローバック</strong>：修正再表示、不正行為、法令違反、リスク管理の失敗が明らかになった場合、会社は<strong>支給済みの報酬を取り戻せる</strong>。</li></ul><p><strong>議決権。</strong> <strong>単純議決</strong>（1 株 1 議決権）と<strong>種類株式</strong>の対比。後者では創業者や経営者が一般株主より議決権の多い株式を持ち、少数株主との潜在的な対立がある。</p><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>CEO と議長の分離はプラスだが、それがすべてではない。独立性の低さ、長い在任期間、一族や内部者の支配があれば、取締役会はなお弱くなりうる。</p></div><h2 id="esg-要因の特定" tabindex="-1">ESG 要因の特定 <a class="header-anchor" href="#esg-要因の特定" aria-label="Permalink to &quot;ESG 要因の特定&quot;">​</a></h2><p>最大の課題は、<strong>目的適合的で、比較可能で、意思決定に有用な</strong>情報を得ることである。ESG データは主に公開書類とサステナビリティ報告書（独立した保証を受けている場合もいない場合もある）から得られる。ESG 開示の多くは<strong>任意</strong>で<strong>一貫性がない</strong>が、時とともに増えてきた。</p><p><strong>重要性（マテリアリティ）。</strong> ESG の問題は、プラスであれマイナスであれ、会社の事業、財務業績、証券の評価に影響すると予想されるなら重要である。会社は、投資家が重要と考えるマイナスの情報を軽く扱う一方で、プラスだが重要でない情報を「重要」と呼ぶことがある。</p><p><strong>投資期間。</strong> 問題が重要かどうかは期間にもよる。</p><ul><li>債券は満期がさまざまなので、期間は<strong>信用アナリスト</strong>にとって特に重要である。</li><li>規制の変更や石油流出などの論争の後、問題の期間は長期から短期に（あるいはその逆に）変わりうる。</li><li>例えば、ある製造業者が将来のより厳しい環境規制に直面する。短期の投資家は目先の利益への影響は小さいと見るが、長期の投資家は高額な工場の改修や罰金を予想する。</li></ul><p><strong>業界ごとの関連要因。</strong> ガバナンスのベスト・プラクティスは会社間でかなり共通している（地域による違いはある）。環境と社会の要因には<strong>世界共通のベスト・プラクティスはなく</strong>、関連性は業界による。エネルギー会社は<strong>環境</strong>要因に、銀行は<strong>社会</strong>要因（データ・セキュリティ、プライバシー、顧客満足）にさらされやすく、どちらもガバナンスにさらされる。</p><p><strong>ESG 要因を特定する 3 つの方法</strong>（単独または組み合わせ）：</p><table tabindex="0"><thead><tr><th>方法</th><th>内容</th><th>例</th></tr></thead><tbody><tr><td><strong>独自の手法</strong></td><td>アナリストや会社自身の判断とツール。会社、ニュース、業界・環境団体、労働組織、専門家、政府の情報を使う</td><td>年次報告書、サステナビリティ報告書、委任状説明書、10-K。TCFD に沿った気候シナリオ開示（移行リスクと物理的リスク）</td></tr><tr><td><strong>ESG データ提供会社</strong></td><td>ベンダーが公開情報を ESG スコアとランキング（業界内の相対評価が多い）に変換し、アナリストの主観的評価も加える</td><td>MSCI、Sustainalytics</td></tr><tr><td><strong>非営利のイニシアチブと報告フレームワーク</strong></td><td>ESG の問題に関するデータ、知見、ツール</td><td>IIRC（標準化された開示フレームワーク）、GRI（業界別のサステナビリティ報告基準）、SASB（統一的なサステナビリティ会計基準。<strong>マテリアリティ・マップ</strong>）、2DII、Access to Nutrition Index</td></tr></tbody></table><p>開示は最小限のものから何ページにもわたるものまであり、比較を難しくしている。例えば GRI の耐久消費財と家庭用品・パーソナルケア製品のトピックには、環境面（原材料の調達、包装、プラスチックと化学物質、製品のエネルギー効率）、社会面（移民労働者、製品の安全性、表示、電子廃棄物）、その他（役員報酬、統治機関の性別構成、仕入先の審査）がある。</p><h2 id="esg-インテグレーション" tabindex="-1">ESG インテグレーション <a class="header-anchor" href="#esg-インテグレーション" aria-label="Permalink to &quot;ESG インテグレーション&quot;">​</a></h2><p>ESG インテグレーションは、機会を見いだし、下方リスクを減らすことを目指す。</p><table tabindex="0"><thead><tr><th></th><th>株式</th><th>債券（信用）</th></tr></thead><tbody><tr><td>目的</td><td><strong>機会を見いだし</strong>、下方リスクを減らす</td><td>主に<strong>下方リスクを減らす</strong>（最良の場合でも額面での償還）</td></tr><tr><td>手法</td><td>財務数値と比率の予測、評価の入力値（例：<strong>割引率</strong>）の調整、感応度・シナリオ分析</td><td>社内の信用評価、比率の予測、相対的な信用順位付け。相対価値、<strong>スプレッド</strong>、<strong>デュレーション</strong>、感応度・シナリオ分析</td></tr><tr><td>例</td><td>ホテル：従業員の離職率が高いので営業費用を引き上げる。菓子メーカー：主要原料を持続可能なものに切り替えたので割引率を<strong>下げる</strong></td><td>玩具メーカー：訴訟が信用比率、キャッシュフロー、流動性を損ない、スプレッドが拡大しうる。石炭会社：座礁資産のリスクは <strong>1 年</strong>債より <strong>10 年</strong>債にはるかに大きく効く</td></tr></tbody></table><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>株式と信用で特定と統合のプロセスは似ているが、<strong>重要な要因とその含意は異なり</strong>、信用（と CDS）への影響は<strong>満期</strong>によって異なりうる。</p></div><h3 id="グリーンボンド" tabindex="-1">グリーンボンド <a class="header-anchor" href="#グリーンボンド" aria-label="Permalink to &quot;グリーンボンド&quot;">​</a></h3><p><strong>グリーンボンド</strong>は、環境や気候に便益のあるプロジェクトに資金を供給する。調達資金は特定のグリーン・プロジェクトに充てられる。</p><ul><li>最初のものは欧州投資銀行の Climate Awareness Bond で、<strong>2007 年</strong>に発行された。</li><li>発行体は主幹事とともに「グリーン」のラベルを決め、適格基準と資金使途を開示しなければならず、独立したレビューを依頼することもある。<strong>グリーンボンド原則</strong>（2014 年。任意。ICMA が管理）がこれを導く。指数提供会社、格付会社、Climate Bonds Initiative には独自の手法があり、欧州委員会も基準を策定している。</li><li>発行体にとっては、追加の監視・報告コストがかかるが、投資家層が広がり、発行時の利回りが下がる可能性がある。</li><li>形態：普通社債、プロジェクト債、MBS/ABS、地方債（例：カリフォルニア州が 2014 年に発行した US$3 億のグリーン一般財源債。他の GO 債と同じく一般会計で裏付けられる）。</li><li>他の条件が同じなら、発行体の通常の債券と<strong>格付も評価も同じ</strong>である。資金使途が違うだけで、債券保有者の遡求権は同じである。</li><li>リスクが低いからではなく、<strong>需要のために</strong>プレミアム（より狭いスプレッド）で取引されることがある。</li><li>リスク：<strong>グリーンウォッシング</strong>（グリーンという特徴に払いすぎる、あるいは環境上の運用方針を満たさない債券を持つ）と<strong>流動性</strong>（保有者の多くは満期保有する）。</li></ul><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>グリーンボンドの信用リスクは発行体の信用リスクである。スプレッドが狭いのは<strong>需要</strong>を反映したもので、デフォルト・リスクが低いからではない。</p></div><h2 id="esg-のリスクと機会の評価" tabindex="-1">ESG のリスクと機会の評価 <a class="header-anchor" href="#esg-のリスクと機会の評価" aria-label="Permalink to &quot;ESG のリスクと機会の評価&quot;">​</a></h2><p>インテグレーションのプロセス：</p><ol><li>会社とその業界にとって<strong>重要な</strong> ESG 要因を特定する。</li><li>それを時系列で、予測の中で、同業他社と比べて評価する。</li><li>財務諸表とバリュエーションを調整する。</li></ol><table tabindex="0"><thead><tr><th>どこで</th><th>典型的な ESG 調整</th></tr></thead><tbody><tr><td>損益計算書 / キャッシュフロー</td><td>売上高、営業費用と営業外費用、利益率、利益、設備投資</td></tr><tr><td>貸借対照表</td><td><strong>減損資産</strong>の見積り</td></tr><tr><td>株式のバリュエーション</td><td>資本コスト / <strong>割引率</strong>、株価倍率、ターミナル・バリュー</td></tr><tr><td>債券のバリュエーション</td><td><strong>信用スプレッド</strong>または CDS</td></tr></tbody></table><p><em>Guidance and Case Studies for ESG Integration: Equities and Fixed Income</em>（2018）のフレームワークは、リサーチ（定性・定量）、証券の評価、ポートフォリオ構築、資産配分、シナリオ分析、リスク管理を対象とする。</p><p>テキストの 3 つのケースはそれぞれ 1 つの柱に焦点を当てている。考え方は他の業界にも当てはまる。</p><table tabindex="0"><thead><tr><th>ケース</th><th>柱</th><th>主要な指標</th><th>財務上の調整</th><th>バリュエーションへの影響</th></tr></thead><tbody><tr><td><strong>Frizzle Drinks</strong>（米国の飲料）</td><td>環境</td><td><strong>水使用原単位</strong> = 製品 1 リットルあたりの水のリットル数（同業他社比較のため売上高 US$100 万あたりで基準化）</td><td>2009 年から 2021 年に 27% 低下し、2025 年までにさらに 13% の削減が目標。2022 年予想の COGS/売上高は 40%（同業他社 42%）で、水使用の減少によりさらに 1% 下げる → 売上総利益率が上がる</td><td>利益の増加 → 株式の公正価値が上がる。債券と CDS にとっては営業キャッシュフローの改善。ESG リスクの低下が<strong>すでにスプレッドに織り込まれているか</strong>を確認する</td></tr><tr><td><strong>Well Pharma</strong>（欧州の製薬）</td><td>社会</td><td><strong>製品の品質</strong>：論争、規制当局の警告書、リコール、罰金、認証を受けた工場の割合（例：ISO 9001）</td><td>同業他社で最悪の記録（警告書 15 通、品質の論争 5 件）。翌年の売上高 −2%、COGS/売上高 +1.3%、営業外費用は営業利益の +4.5%。扱いは問題が<strong>繰り返し起きるか一度きりか</strong>による</td><td>株主<strong>にも</strong>債券保有者にも利益とキャッシュフローの減少。ブランド価値の減損の可能性</td></tr><tr><td><strong>Sumiyoshi</strong>（日本の銀行）</td><td>ガバナンス</td><td>同業他社と比べた取締役会の構成。ガバナンスの代理指標としての<strong>不良債権 / 総貸出金</strong></td><td>不良債権比率が同業他社より 50 bp 高い</td><td>株式リスク・プレミアムの上昇。信用スプレッドの拡大</td></tr></tbody></table><p>Well Pharma の品質問題が財務にどう波及するか：</p><table tabindex="0"><thead><tr><th>要因</th><th>財務への影響</th></tr></thead><tbody><tr><td>製品品質の論争</td><td>ブランドの毀損 → 売上の減少</td></tr><tr><td>規制当局の警告書</td><td>コンプライアンス費用の増加</td></tr><tr><td>製品リコール</td><td>売上の喪失、リコール費用</td></tr><tr><td>規制上の罰金</td><td>返品や訴訟に対する引当金</td></tr><tr><td>認証を受けた工場の割合が低い</td><td>品質問題、リコール、費用のリスクが高い</td></tr></tbody></table>',53)])])}const c=r(n,[["render",g]]);export{p as __pageData,c as default};
